class Solution {
public:
    string sortSentence(string s) {
        vector<string> words;
        stringstream ss(s);
        string w;
        while (ss >> w) words.push_back(w);
        vector<string> res(words.size());
        for (auto& t : words) {
            int pos = t.back() - '1';
            t.pop_back();
            res[pos] = t;
        }
        string out;
        for (int i = 0; i < (int)res.size(); ++i) {
            if (i) out += ' ';
            out += res[i];
        }
        return out;
    }
};

