class Solution {
public:
    string sortSentence(string s) {
        vector<string> words;
        stringstream ss(s);
        string w;
        while (ss >> w) words.push_back(w);
        sort(words.begin(), words.end(),
             [](const string& a, const string& b) { return a.back() < b.back(); });
        string out;
        for (auto& t : words) {
            t.pop_back();
            if (!out.empty()) out += ' ';
            out += t;
        }
        return out;
    }
};

